import React from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import Yagr from '@gravity-ui/yagr';
import {CpuChart} from './monitoring/CpuChart';
import {createMockCpuSource} from './monitoring/cpuSource';

// --- instrumentation -------------------------------------------------------
const w = window as any;
const listeners = new Map<string, number>();
const key = (t: any, type: string) => `${t === window ? 'window' : t === document ? 'document' : t?.constructor?.name}:${type}`;
const add = EventTarget.prototype.addEventListener, rem = EventTarget.prototype.removeEventListener;
EventTarget.prototype.addEventListener = function (type: string, ...a: any[]) { listeners.set(key(this, type), (listeners.get(key(this, type)) ?? 0) + 1); return (add as any).call(this, type, ...a); };
EventTarget.prototype.removeEventListener = function (type: string, ...a: any[]) { listeners.set(key(this, type), (listeners.get(key(this, type)) ?? 0) - 1); return (rem as any).call(this, type, ...a); };
const liveObservers = new Set<any>();
const RO = window.ResizeObserver;
w.ResizeObserver = class extends RO {
  n = 0;
  observe(t: Element, o?: any) { this.n++; liveObservers.add(this); super.observe(t, o); }
  unobserve(t: Element) { this.n--; if (this.n <= 0) liveObservers.delete(this); super.unobserve(t); }
  disconnect() { this.n = 0; liveObservers.delete(this); super.disconnect(); }
};
const timings: number[] = [];
const origSet = (Yagr as any).prototype.setSeries;
(Yagr as any).prototype.setSeries = function (...args: any[]) { const t0 = performance.now(); const r = origSet.apply(this, args); timings.push(performance.now() - t0); return r; };
const frames: number[] = [];
let last = performance.now();
const loop = () => { const n = performance.now(); frames.push(n - last); last = n; requestAnimationFrame(loop); };
requestAnimationFrame(loop);
const errors: string[] = [];
window.addEventListener('error', (e) => errors.push('error: ' + e.message));
window.addEventListener('unhandledrejection', (e) => errors.push('rejection: ' + e.reason));
const origErr = console.error; console.error = (...a: any[]) => { errors.push('console.error: ' + a.join(' ').slice(0, 300)); origErr(...a); };

w.__diag = () => ({
  listeners: Object.fromEntries([...listeners].filter(([, v]) => v !== 0)),
  observers: liveObservers.size,
  canvases: document.querySelectorAll('canvas').length,
  tooltips: document.querySelectorAll('.yagr-tooltip').length,
  bodyChildren: document.body.children.length,
  errors,
});
w.__timings = () => { const t = timings.slice(); timings.length = 0; return t; };
w.__frames = () => { const f = frames.slice(); frames.length = 0; return f; };

// --- harness ----------------------------------------------------------------
let root: ReactDOM.Root | null = null;
let setDarkExt: (d: boolean) => void = () => {};
function Harness({stepMs, windowMs}: {stepMs: number; windowMs: number}) {
